/*
 * socket.io.min.js 的**兼容替代品**（不是 socket.io 本体）
 * ---------------------------------------------------------------------------
 * 为什么不用真的 socket.io：
 *   socket.io 的服务端协议（Engine.IO v4）要在 ESP32-S3 上实现一整套
 *   帧解析、会话管理、长轮询升级、ping/pong、二进制附件 ——
 *   几百行 C，且每个细节错了都是「手机连上了但按键没反应」这种难查的问题。
 *
 * 为什么这样能行：
 *   movo 的 APK 只是个 WebView 壳（MainActivity.kt 只做「存地址 + 加载 URL +
 *   把 navigator.vibrate 接到马达」），**页面是从服务端拿的**。
 *   而页面里的 `<script src="/static/js/socket.io.min.js">` 也是从服务端拿的。
 *   所以我们把这个文件换成一份 API 等价的实现，movo 的页面**一行都不用改**。
 *
 * 本实现覆盖 movo 页面真正用到的那几个方法（已全量 grep 确认）：
 *   global.io(options)                 → 返回 socket
 *   socket.on(ev, cb)                  → 'connect'/'disconnect'/'connect_error'
 *                                         与服务端推来的 'voice_state'/
 *                                         'voice_partial'/'voice_final'
 *   socket.emit(ev, data)              → 无回执
 *   socket.emit(ev, data, ackCb)       → 有回执（res.ok / res.msg）
 *   socket.timeout(ms).emit(ev,d,cb)   → 超时则 cb(err)
 *   socket.connected                   → 布尔
 *   socket.connect() / socket.disconnect()
 *   socket.id
 *
 * 传输：POST /io 发事件，GET /io/poll 收服务端事件。
 */
(function (global) {
    'use strict';

    var POLL_MS = 250;

    /* ----------------------------------------------------------------
     * ★ BLE 传输（手机直连板子，不走 WiFi）★
     *   装了新 APK 的手机页面上存在 window.MovoBle（Java 注入的桥）：
     *     MovoBle.call('move', "dx,dy")   高频指针 → type2 二进制帧
     *     MovoBle.call('emit', json)      JSON 控制帧 {"ev":..,"data":..}
     *     MovoBle.call('voice', "f|b64")  语音 ADPCM 包（f=整段第一包）
     *   板子推回来的事件由 Java 端调 window.__movoBleEvent(json)。
     *   有 MovoBle 就完全不走 HTTP（fetch/轮询都不发）。
     * ---------------------------------------------------------------- */
    function bleBridge() {
        try {
            return (global.MovoBle && typeof global.MovoBle.call === 'function')
                ? global.MovoBle : null;
        } catch (e) { return null; }
    }

    var BLE_SHIMS = [];

    /* 板子→页面：JSON 就是原来 HTTP 轮询拿到的 {ev,data} */
    global.__movoBleEvent = function (json) {
        var m = null;
        try { m = (typeof json === 'string') ? JSON.parse(json) : json; } catch (e) { return; }
        if (!m || !m.ev) return;
        for (var i = 0; i < BLE_SHIMS.length; i++) {
            try { BLE_SHIMS[i]._emitLocal(m.ev, m.data); } catch (e) { }
        }
    };

    /*
     * 连接状态：0 空闲 / 1 扫描 / 2 连接中 / 3 发现服务 / 4 就绪
     *
     * ★ BLE 模式下「已连接」不能跟着状态回调来回翻转 ★
     *
     *   以前这里把 _connected 直接设成 (st===4)，于是：
     *     · 页面在 setState(4) 之前就加载完 → 那条回调被错过；
     *     · 板子刷机/走远断链 → 状态回 0 → _connected=false；
     *   之后页面就**永远认为没连上**，_post 直接返回
     *   {"ok":false,"msg":"not connected"}，所有事件（包括打字）全被丢掉。
     *   用户看到的就是「重连后打字传不到」。
     *
     *   现在：BLE 模式下页面始终视为「已连接」，事件由原生发送队列排队，
     *   链路恢复后自动补发；状态只用来触发 connect/disconnect 通知。
     */
    global.__movoBleState = function (st) {
        for (var i = 0; i < BLE_SHIMS.length; i++) {
            var s = BLE_SHIMS[i];
            if (st === 4 && !s._bleReady) {
                s._bleReady = true;
                s._connected = true;
                s._emitLocal('connect', {});
            }
        }
    };

    function utf8Bytes(str) {
        try { return new TextEncoder().encode(str); } catch (e) { }
        /* 老 WebView 兜底：逐字符算 UTF-8 长度 */
        var n = 0;
        for (var i = 0; i < str.length; i++) {
            var c = str.charCodeAt(i);
            n += c < 0x80 ? 1 : (c < 0x800 ? 2 : (c >= 0xD800 && c <= 0xDBFF ? 4 : 3));
        }
        return { length: n };
    }

    function abToBase64(buf) {
        var bytes = new Uint8Array(buf);
        var s = '';
        for (var i = 0; i < bytes.length; i += 0x2000) {
            s += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(i + 0x2000, bytes.length)));
        }
        return global.btoa(s);
    }

    function Shim(opts) {
        opts = opts || {};
        this._handlers = {};
        this._connected = false;
        this._id = null;
        this._pollTimer = null;
        this._pollPaused = false;
        this._stopped = false;
        this._pending = 0;
        this._url = (global.location && global.location.origin) || '';
        this._ble = bleBridge();
        if (this._ble) {
            /* BLE：页面侧永远「可用」，真实收发由原生队列负责 */
            this._bleReady = true;
            BLE_SHIMS.push(this);
        }
        this._onConnect();
    }

    Shim.prototype._onConnect = function () {
        var self = this;
        this._connected = true;
        this._id = 'shim-' + Date.now().toString(36);
        this._emitLocal('connect', {});
        /* 立刻开始收服务端事件 */
        this._schedulePoll(0);
    };

    Shim.prototype._emitLocal = function (ev, data) {
        var cbs = this._handlers[ev];
        if (!cbs) return;
        for (var i = 0; i < cbs.length; i++) {
            try { cbs[i](data); } catch (e) { }
        }
    };

    /* ---------------------------------------------------------- 发事件 */

    /*
     * ★ move 事件要合并 ★
     *   手指在触控板上划一下，页面每秒能发十几个 move；
     *   一条一个 HTTP 请求，板子那边光建会话就要建十几回 ——
     *   浏览器那 6 条连接也被占满，轮询被挤掉，页面就卡住了。
     *   这里把 33ms 内的 move 攒成一条（dx/dy 相加，位移总量不变）。
     */
    var MOVE_INTERVAL_MS = 33;
    var _moveTimer = null;
    var _moveAcc = null;

    function flushMove(self) {
        if (_moveTimer) { clearTimeout(_moveTimer); _moveTimer = null; }
        if (!_moveAcc) return;
        var acc = _moveAcc;
        _moveAcc = null;
        /* ★ 必须走 _post，不能走 emit ★
           emit 会把 move 再拦回 _queueMove —— 合并→flush→再合并，
           死循环，永远发不出去（现象：触摸板/陀螺仪光标完全不动）。 */
        self._post('move', acc);
    }

    Shim.prototype._queueMove = function (data) {
        var self = this;
        if (!_moveAcc) {
            _moveAcc = {};
            for (var k in data) { if (Object.prototype.hasOwnProperty.call(data, k)) _moveAcc[k] = data[k]; }
        } else {
            _moveAcc.dx = (_moveAcc.dx || 0) + (data.dx || 0);
            _moveAcc.dy = (_moveAcc.dy || 0) + (data.dy || 0);
        }
        if (!_moveTimer) {
            _moveTimer = setTimeout(function () { flushMove(self); }, MOVE_INTERVAL_MS);
        }
    };

    Shim.prototype.emit = function (ev, data, ack, opts) {
        if (ev === 'move' && data && typeof data === 'object' && !ack) {
            this._queueMove(data);
            return this;
        }
        return this._post(ev, data, ack, opts);
    };

    Shim.prototype._post = function (ev, data, ack, opts) {
        if (!this._connected) {
            /* 未连接：socket.io 的行为是丢弃，不排队 */
            if (typeof ack === 'function') {
                try { ack({ ok: false, msg: 'not connected' }); } catch (e) { }
            }
            return this;
        }
        var self = this;
        var isBinary = (typeof ArrayBuffer !== 'undefined' && data instanceof ArrayBuffer) ||
                       (typeof Blob !== 'undefined' && data instanceof Blob);

        if (this._ble) return this._postBle(ev, data, ack, isBinary);

        var url = this._url + '/io';
        var init = { method: 'POST', headers: {} };

        if (isBinary) {
            /* 二进制（语音 PCM）：原始 body，事件名放请求头 */
            init.headers['X-Event'] = ev;
            init.body = data;
        } else {
            init.headers['Content-Type'] = 'application/json';
            init.body = JSON.stringify({ ev: ev, data: (data === undefined ? null : data) });
        }

        /*
         * ★ 单请求超时（可选）★
         *   板子的 HTTP 是单任务：一个请求卡住，整台板子的网页都跟着卡。
         *   语音 PCM 一包几 KB，链路抖动时会挂十几秒 ——
         *   没有超时的话，录音队列会一直堵在第一个包上，后面全丢。
         *   超时后直接放弃这一包（宁可少一点音频，也不能卡死整条链路）。
         */
        var ms = opts && opts.timeout;
        var ctrl = null, timer = null, done = false;
        if (ms && typeof AbortController !== 'undefined') {
            try {
                ctrl = new AbortController();
                init.signal = ctrl.signal;
                timer = setTimeout(function () { try { ctrl.abort(); } catch (e) { } }, ms);
            } catch (e) { ctrl = null; timer = null; }
        }
        function finish(res) {
            if (done) return;
            done = true;
            if (timer) { clearTimeout(timer); timer = null; }
            if (typeof ack === 'function') {
                /*
                 * 回执形状与 movo 服务端一致：**扁平的** {ok, msg}。
                 * 不做 res.data 拆包 —— movo 的 sys_action 回调直接读 res.ok。
                 */
                try { ack(res || { ok: false, msg: 'no response' }); } catch (e) { }
            }
        }

        fetch(url, init).then(function (r) {
            return r.json().catch(function () { return { ok: true }; });
        }).then(function (res) {
            finish(res || { ok: false, msg: 'no response' });
        }).catch(function (err) {
            var msg = (err && err.name === 'AbortError') ? 'timeout' : String(err);
            finish({ ok: false, msg: msg });
        });
        return this;
    };

    /*
     * BLE 传输版 _post。
     * ★ 载荷上限 ★ 板子 MTU 247 → 一帧 240 字节载荷。
     *   JSON 帧塞不下（中文 3 字节/字），type_text 在这里按字节切成多帧，
     *   板子依次上报，PC 依次打出，用户看到的就是连续输入。
     */
    Shim.prototype._postBle = function (ev, data, ack, isBinary) {
        var B = this._ble;
        var ok = true, msg = '';
        try {
            if (ev === 'move' && data) {
                ok = (B.call('move', Math.round(data.dx || 0) + ',' + Math.round(data.dy || 0)) !== 'no');
            } else if (isBinary) {
                if (!(typeof ArrayBuffer !== 'undefined' && data instanceof ArrayBuffer)) {
                    ok = false; msg = 'blob unsupported';
                } else {
                    var first = (ev === 'voice_adpcm_first');
                    var b64 = abToBase64(data);
                    ok = (B.call('voice', (first ? 'f|' : 'n|') + b64) !== 'no');
                }
            } else {
                var payload = (data === undefined) ? null : data;
                var txt = (ev === 'type_text' && payload && typeof payload.text === 'string')
                    ? payload.text : null;
                if (txt !== null && utf8Bytes(txt).length > 130) {
                    /* 太长的文本拆成多帧，每帧 JSON 控制在 ~190 字节内 */
                    var rest = txt, firsty = true;
                    while (rest.length) {
                        var take = rest.length, cut = -1;
                        for (var i = rest.length; i > 0; i--) {
                            var piece = rest.slice(0, i);
                            if (utf8Bytes(JSON.stringify({ ev: ev, data: { text: piece } })).length <= 190) {
                                cut = i; break;
                            }
                        }
                        if (cut <= 0) cut = 1;
                        var part = rest.slice(0, cut);
                        rest = rest.slice(cut);
                        var j1 = JSON.stringify({ ev: ev, data: { text: part } });
                        if (B.call('emit', j1) === 'no') { ok = false; break; }
                        firsty = false;
                    }
                } else {
                    var json = JSON.stringify({ ev: ev, data: payload });
                    ok = (B.call('emit', json) !== 'no');
                }
            }
        } catch (e) { ok = false; msg = String(e); }
        if (typeof ack === 'function') {
            try { ack(ok ? { ok: true } : { ok: false, msg: msg || 'ble' }); } catch (e) { }
        }
        return this;
    };

    /* socket.timeout(ms).emit(ev, data, cb) —— 超时回执走 error-first */
    Shim.prototype.timeout = function (ms) {
        var self = this;
        return {
            emit: function (ev, data, cb) {
                var done = false;
                var timer = setTimeout(function () {
                    if (done) return;
                    done = true;
                    if (typeof cb === 'function') {
                        try { cb(new Error('timeout')); } catch (e) { }
                    }
                }, ms || 0);
                self.emit(ev, data, function (res) {
                    if (done) return;
                    done = true;
                    clearTimeout(timer);
                    if (typeof cb === 'function') {
                        /* socket.io 的 timeout 形式是 error-first：成功时 err 为 null */
                        try { cb(null, res); } catch (e) { }
                    }
                });
                return this;
            }
        };
    };

    /* ---------------------------------------------------- 收服务端事件 */
    Shim.prototype._schedulePoll = function (delay) {
        var self = this;
        /* BLE 模式是推送，没有轮询这回事（file:// 页面也没有同源可 fetch） */
        if (this._ble) return;
        if (this._stopped) return;
        if (this._pollTimer) clearTimeout(this._pollTimer);
        this._pollTimer = setTimeout(function () {
            self._pollTimer = null;
            self._poll();
        }, delay === undefined ? POLL_MS : delay);
    };

    Shim.prototype._poll = function () {
        var self = this;
        if (this._stopped) return;
        fetch(this._url + '/io/poll', { method: 'GET', cache: 'no-store' })
            .then(function (r) { return r.json(); })
            .then(function (list) {
                if (list && list.length) {
                    for (var i = 0; i < list.length; i++) {
                        var m = list[i];
                        if (m && m.ev) self._emitLocal(m.ev, m.data);
                    }
                }
                /* 录音期间暂停轮询：板子的 HTTP 是单任务，
                   轮询和 PCM 抢同一个任务 → PCM 延迟被拉长好几倍。 */
                if (!self._pollPaused) self._schedulePoll(POLL_MS);
            })
            .catch(function () {
                /* 收不到就退避重连，语义上等同 socket.io 的 disconnect/connect_error */
                self._connected = false;
                self._emitLocal('connect_error', {});
                self._emitLocal('disconnect', {});
                self._schedulePoll(1000);
            });
    };

    /*
     * ★ 录音时把轮询停下来 ★
     *   板子那边 HTTP 是**单任务**：一个会话在处理，所有会话都得排队。
     *   轮询每 250ms 一次，PCM 每 100ms 一包 —— 两者叠加，
     *   PCM 的往返时间被拉长到几百毫秒，语音就断了。
     *   暂停期间不丢东西：板子的事件队列会留着，恢复后立刻补取。
     */
    Shim.prototype.setPollPaused = function (paused) {
        var was = this._pollPaused;
        this._pollPaused = !!paused;
        if (this._pollPaused) {
            if (this._pollTimer) { clearTimeout(this._pollTimer); this._pollTimer = null; }
        } else if (was) {
            this._schedulePoll(0);   /* 恢复：马上补取积压的事件 */
        }
        return this;
    };

    /* ------------------------------------------------------------ 接口 */
    Shim.prototype.on = function (ev, cb) {
        if (typeof cb !== 'function') return this;
        if (!this._handlers[ev]) this._handlers[ev] = [];
        this._handlers[ev].push(cb);
        return this;
    };

    Shim.prototype.off = function (ev, cb) {
        var cbs = this._handlers[ev];
        if (!cbs) return this;
        if (!cb) { delete this._handlers[ev]; return this; }
        var i = cbs.indexOf(cb);
        if (i >= 0) cbs.splice(i, 1);
        return this;
    };

    Shim.prototype.connect = function () {
        if (this._connected) return this;
        this._stopped = false;
        this._onConnect();
        return this;
    };

    Shim.prototype.disconnect = function () {
        this._stopped = true;
        if (this._pollTimer) { clearTimeout(this._pollTimer); this._pollTimer = null; }
        if (this._connected) {
            this._connected = false;
            this._emitLocal('disconnect', {});
        }
        return this;
    };

    Object.defineProperty(Shim.prototype, 'connected', {
        get: function () { return this._connected; }
    });
    Object.defineProperty(Shim.prototype, 'id', {
        get: function () { return this._id; }
    });

    global.io = function (opts) { return new Shim(opts); };
    global.__movoShim = true;
})(window);
